add_action( 'pre_ping', 'perfectpixel_disable_self_pingbacks' );

function perfectpixel_disable_self_pingbacks( &$links ) {
	$home = untrailingslashit( preg_replace( '#^https?:#i', '', home_url() ) );
	foreach ( $links as $key => $link ) {
		if ( 0 === stripos( preg_replace( '#^https?:#i', '', $link ), $home ) ) {
			unset( $links[ $key ] );
		}
	}
}
